// ═══════════════════════════════════════════════
// TARGO - MAPEO DE DATOS DEL FORMULARIO WEB
// ═══════════════════════════════════════════════

const body = $json.body;

// Validación de campos obligatorios
const camposRequeridos = ['nombre', 'cedula', 'whatsapp', 'municipio', 'departamento',
  'tipo_vehiculo', 'placa', 'capacidad_ton', 'estado_vehiculo', 'carroceria', 'disponibilidad'];
const faltantes = camposRequeridos.filter(c => !body[c]);
if (faltantes.length > 0) {
  throw new Error('Campos obligatorios faltantes: ' + faltantes.join(', '));
}

// Convierte un array JS al formato nativo de array de Postgres: {"a","b"}
// (el driver de Postgres NO acepta JSON.stringify de un array para columnas text[])
function toPgArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return null;
  const items = arr.map(v => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"');
  return '{' + items.join(',') + '}';
}

const wppDigits = String(body.whatsapp || '').replace(/\D/g, '');
const telefono = wppDigits.startsWith('57') ? wppDigits : '57' + wppDigits;
const cedula = String(body.cedula || '').replace(/\D/g, '');
const placa = String(body.placa || '').toUpperCase().trim();
const tipos_carga = Array.isArray(body.tipos_carga) ? body.tipos_carga : [];
const especies_viva  = Array.isArray(body.especies_carga_viva) ? body.especies_carga_viva : [];
const dptos_op    = Array.isArray(body.departamentos_operacion) ? body.departamentos_operacion : [];

return {
  cedula,
  telefono,
  nombre:                   body.nombre,
  tel_alterno:              body.tel_alterno              || null,
  municipio:                body.municipio,
  departamento:             body.departamento,
  tipo_vehiculo:            body.tipo_vehiculo,
  placa,
  color_vehiculo:           body.color_vehiculo           || null,
  marca:                    body.marca                    || null,
  capacidad_ton:            body.capacidad_ton,
  estado_vehiculo:          body.estado_vehiculo,
  carroceria:               body.carroceria,
  tipos_carga:              toPgArray(tipos_carga),
  especies_carga_viva:      toPgArray(especies_viva),
  departamentos_operacion:  toPgArray(dptos_op),
  tipo_vias:                body.tipo_vias                || null,
  disponibilidad:           body.disponibilidad,
  fecha_disponible:         body.fecha_disponible         || null,
  experiencia_anios:        body.experiencia_anios        || null,
  notas:                    body.notas                    || null,
  tipo_usuario:             'TRANSPORTISTA',
  fuente:                   'formulario_web',
  fecha_registro:           new Date().toISOString()
};

