// ═══════════════════════════════════════════════════════════════
// TARGO — Procesar Respuesta de Solicitud de Carga (v5)
// Añade un resumen de confirmación al final: antes de buscar
// transportista, se le muestra al productor todo lo que respondió
// y puede decir *Sí* (confirmar), *Cancelar* (empezar de nuevo), o
// el número del dato que quiere corregir.
// ═══════════════════════════════════════════════════════════════

const PREGUNTAS = {
  cantidad_camiones: '🚛 ¿Cuántos camiones necesitas para esta carga?',
  tipo_carga: '🌾 ¿Qué tipo de carga vas a mover? (ej: ganado, café, plátano, grano...)',
  cantidad_animales: '🐄 ¿Cuántos animales vas a mover?',
  peso_promedio_animal: '⚖️ ¿Cuál es el peso promedio por animal, en kilos? (ej: 450)',
  peso_toneladas: '⚖️ ¿Cuántas toneladas aproximadamente?',
  vereda: '📍 ¿En qué vereda o finca está la carga?',
  departamento_origen: '🗺️ ¿En qué departamento queda? (ej: Meta, Valle del Cauca, Cundinamarca...)',
  punto_referencia: '📌 ¿Cerca de qué pueblo o punto conocido queda? (nos ayuda a ubicarla bien)',
  tipo_via: '🛣️ ¿Cómo es la vía de acceso? Responde: *Pavimentada*, *Destapada*, o *Solo camioneta*',
  destino: '🏁 ¿A dónde va la carga? (ciudad o municipio)',
  fecha_requerida: '📅 ¿Para qué fecha necesitas el transporte? (ej: *hoy*, *mañana*, o una fecha como *25/08*)',
};

const ICONOS = {
  cantidad_camiones: '🚛',
  tipo_carga: '🌾',
  cantidad_animales: '🐄',
  peso_promedio_animal: '⚖️',
  peso_toneladas: '⚖️',
  vereda: '📍',
  departamento_origen: '🗺️',
  punto_referencia: '📌',
  tipo_via: '🛣️',
  destino: '🏁',
  fecha_requerida: '📅',
};

const ETIQUETAS = {
  cantidad_camiones: 'Camiones',
  tipo_carga: 'Tipo de carga',
  cantidad_animales: 'Animales',
  peso_promedio_animal: 'Peso/animal (kg)',
  peso_toneladas: 'Peso (ton)',
  vereda: 'Vereda/finca',
  departamento_origen: 'Departamento',
  punto_referencia: 'Punto de ref.',
  tipo_via: 'Vía',
  destino: 'Destino',
  fecha_requerida: 'Fecha',
};

const DEPARTAMENTOS = [
  'Amazonas', 'Antioquia', 'Arauca', 'Atlántico', 'Bolívar', 'Boyacá',
  'Caldas', 'Caquetá', 'Casanare', 'Cauca', 'Cesar', 'Chocó', 'Córdoba',
  'Cundinamarca', 'Guainía', 'Guaviare', 'Huila', 'La Guajira', 'Magdalena',
  'Meta', 'Nariño', 'Norte de Santander', 'Putumayo', 'Quindío', 'Risaralda',
  'San Andrés y Providencia', 'Santander', 'Sucre', 'Tolima', 'Valle del Cauca',
  'Vaupés', 'Vichada',
];

function quitarTildes(s) {
  return s.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

const INDICE_DEPARTAMENTOS = new Map(DEPARTAMENTOS.map((d) => [quitarTildes(d.toLowerCase()), d]));
const ALIAS_DEPARTAMENTOS = {
  'valle': 'Valle del Cauca',
  'norte de santander': 'Norte de Santander',
  'santander norte': 'Norte de Santander',
  'atlantico': 'Atlántico',
  'bogota': 'Cundinamarca',
  'bogotá': 'Cundinamarca',
  'san andres': 'San Andrés y Providencia',
};

function parseDepartamento(texto) {
  const t = quitarTildes((texto || '').trim().toLowerCase());
  if (!t) return null;
  if (INDICE_DEPARTAMENTOS.has(t)) return INDICE_DEPARTAMENTOS.get(t);
  const aliasKey = Object.keys(ALIAS_DEPARTAMENTOS).find((k) => quitarTildes(k) === t);
  if (aliasKey) return ALIAS_DEPARTAMENTOS[aliasKey];
  return null;
}

function normalizar(s) {
  return (s || '').trim();
}

function esGanado(tipoCarga) {
  const t = quitarTildes((tipoCarga || '').toLowerCase());
  return /ganad|vac|toro|novill|\bres(es)?\b|bovin|becerr|ternero/.test(t);
}

function pasosPara(tipoCarga) {
  const pasos = ['cantidad_camiones', 'tipo_carga'];
  if (esGanado(tipoCarga)) {
    pasos.push('cantidad_animales', 'peso_promedio_animal');
  } else {
    pasos.push('peso_toneladas');
  }
  pasos.push('vereda', 'departamento_origen', 'punto_referencia', 'tipo_via', 'destino', 'fecha_requerida');
  return pasos;
}

function parseCantidadCamiones(texto) {
  const m = normalizar(texto).match(/(\d+)/);
  if (!m) return null;
  const val = parseInt(m[1], 10);
  if (isNaN(val) || val <= 0 || val > 20) return null;
  return val;
}

function parseTonelaje(texto) {
  const m = normalizar(texto).replace(',', '.').match(/(\d+(\.\d+)?)/);
  if (!m) return null;
  const val = parseFloat(m[1]);
  if (isNaN(val) || val <= 0 || val > 500) return null;
  return val;
}

function parseCantidadAnimales(texto) {
  const m = normalizar(texto).match(/(\d+)/);
  if (!m) return null;
  const val = parseInt(m[1], 10);
  if (isNaN(val) || val <= 0 || val > 5000) return null;
  return val;
}

function parsePesoPromedioAnimal(texto) {
  const m = normalizar(texto).replace(',', '.').match(/(\d+(\.\d+)?)/);
  if (!m) return null;
  const val = parseFloat(m[1]);
  if (isNaN(val) || val <= 0 || val > 1500) return null;
  return val;
}

function parseTipoVia(texto) {
  const t = normalizar(texto).toLowerCase();
  if (/pavim/.test(t)) return 'pavimentada';
  if (/destap|trocha|tierra/.test(t)) return 'destapada';
  if (/camion|solo.?camio/.test(t)) return 'solo_camioneta';
  return null;
}

function hoyYMD(hoyISO) {
  if (hoyISO) {
    const [y, m, d] = hoyISO.split('-').map(Number);
    return { y, m, d };
  }
  const now = new Date();
  return { y: now.getFullYear(), m: now.getMonth() + 1, d: now.getDate() };
}
function sumarDias({ y, m, d }, dias) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + dias);
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}
function esAnterior(a, b) {
  return (a.y * 10000 + a.m * 100 + a.d) < (b.y * 10000 + b.m * 100 + b.d);
}
function esFechaValida({ y, m, d }) {
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}
function parseFecha(texto, hoyISO) {
  const t = normalizar(texto).toLowerCase();
  const base = hoyYMD(hoyISO);
  if (/^hoy$/.test(t)) return base;
  if (/^ma[ñn]ana$/.test(t)) return sumarDias(base, 1);
  if (/pasado\s*ma[ñn]ana/.test(t)) return sumarDias(base, 2);
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/);
  if (m) {
    const dia = parseInt(m[1], 10);
    const mes = parseInt(m[2], 10);
    let anio = m[3] ? parseInt(m[3], 10) : base.y;
    if (anio < 100) anio += 2000;
    let candidata = { y: anio, m: mes, d: dia };
    if (!esFechaValida(candidata)) return null;
    if (!m[3] && esAnterior(candidata, base)) candidata = { y: anio + 1, m: mes, d: dia };
    return candidata;
  }
  return null;
}
function toISODate({ y, m, d }) {
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function parseSiNo(texto) {
  const t = quitarTildes((texto || '').trim().toLowerCase());
  if (/^(si|s|sisi|claro|dale|listo|correcto|confirmo|ok|vale)$/.test(t)) return true;
  if (/^(no|nel|negativo|nop)$/.test(t)) return false;
  return null;
}

function esCancelar(texto) {
  return /^cancelar$/i.test(quitarTildes(normalizar(texto)));
}

// ── Resumen para confirmación ────────────────────────────────
function resumenCampos(contexto) {
  const pasos = pasosPara(contexto.tipo_carga);
  return pasos.map((campo, i) => ({
    numero: i + 1,
    campo,
    etiqueta: ETIQUETAS[campo],
    valor: contexto[campo],
  }));
}

function formatearValor(campo, valor) {
  if (campo === 'tipo_via') {
    return { pavimentada: 'Pavimentada', destapada: 'Destapada', solo_camioneta: 'Solo camioneta' }[valor] || valor;
  }
  return valor;
}

function textoResumen(contexto) {
  const filas = resumenCampos(contexto)
    .map((f) => `${f.numero}. ${ICONOS[f.campo] || ''} ${f.etiqueta}: *${formatearValor(f.campo, f.valor)}*`)
    .join('\n');
  return `📋 Revisa tu solicitud:\n\n${filas}\n\n¿Todo bien?\n✅ *Sí* — confirmar y buscar transportista\n✏️ El *número* — corregir ese dato\n❌ *Cancelar* — empezar de nuevo`;
}

// ─────────────────────────────────────────────────────────────
function procesar(estadoRow, mensajeTexto, hoyISO) {
  const estado = estadoRow || {};
  let contexto = estado.contexto || {};
  if (typeof contexto === 'string') {
    try { contexto = JSON.parse(contexto); } catch (e) { contexto = {}; }
  }

  const pasoActualKey = (estado.estado_actual || '').replace(/^esperando_/, '');

  // ── "Cancelar" funciona en cualquier paso de la solicitud, no solo al confirmar.
  // Sale del todo del flujo (no vuelve a preguntar cantidad_camiones de inmediato) --
  // el siguiente mensaje del productor se trata como un saludo normal.
  if (esCancelar(mensajeTexto)) {
    return {
      accion: 'cancelado',
      estado_actual: null,
      contexto: {},
      siguiente_pregunta: '❌ Solicitud cancelada. Escríbeme cuando quieras pedir transporte de nuevo. 🙌',
      solicitud_lista: false,
    };
  }

  // ── Paso especial: confirmación final ──
  if (pasoActualKey === 'confirmacion') {
    const si = parseSiNo(mensajeTexto);
    if (si === true) {
      return {
        accion: 'completado',
        estado_actual: null,
        contexto,
        siguiente_pregunta: null,
        solicitud_lista: true,
        solicitud_data: contexto,
      };
    }
    const numero = parseInt(normalizar(mensajeTexto), 10);
    const resumen = resumenCampos(contexto);
    const fila = resumen.find((f) => f.numero === numero);
    if (fila) {
      const nuevoContexto = { ...contexto, _corrigiendo: true };
      return {
        accion: 'avanzar',
        estado_actual: 'esperando_' + fila.campo,
        contexto: nuevoContexto,
        siguiente_pregunta: PREGUNTAS[fila.campo],
        solicitud_lista: false,
      };
    }
    return {
      accion: 'reintentar',
      estado_actual: 'esperando_confirmacion',
      contexto,
      siguiente_pregunta: 'No te entendí 🤔 Responde *Sí*, *Cancelar*, o el número del dato que quieres corregir.',
      solicitud_lista: false,
    };
  }

  const PASOS = pasosPara(contexto.tipo_carga);
  const idx = PASOS.indexOf(pasoActualKey);

  if (idx === -1) {
    return {
      accion: 'reiniciar',
      estado_actual: 'esperando_cantidad_camiones',
      contexto: {},
      siguiente_pregunta: PREGUNTAS.cantidad_camiones,
      solicitud_lista: false,
    };
  }

  const campo = PASOS[idx];
  const corrigiendo = contexto._corrigiendo === true;
  let valorGuardado = null;
  let error = null;

  if (campo === 'cantidad_camiones') {
    valorGuardado = parseCantidadCamiones(mensajeTexto);
    if (valorGuardado === null) error = 'No entendí la cantidad 🤔 Escribe solo el número de camiones, ej: *1*, *2*, *3*';
  } else if (campo === 'peso_toneladas') {
    valorGuardado = parseTonelaje(mensajeTexto);
    if (valorGuardado === null) error = 'No entendí el peso 🤔 Escribe solo el número de toneladas, ej: *8*';
  } else if (campo === 'cantidad_animales') {
    valorGuardado = parseCantidadAnimales(mensajeTexto);
    if (valorGuardado === null) error = 'No entendí la cantidad 🤔 Escribe solo el número de animales, ej: *20*';
  } else if (campo === 'peso_promedio_animal') {
    valorGuardado = parsePesoPromedioAnimal(mensajeTexto);
    if (valorGuardado === null) error = 'No entendí el peso 🤔 Escribe solo el número en kilos, ej: *450*';
  } else if (campo === 'departamento_origen') {
    valorGuardado = parseDepartamento(mensajeTexto);
    if (valorGuardado === null) error = 'No reconocí ese departamento 🤔 Escríbelo tal cual, ej: *Meta*, *Valle del Cauca*, *Cundinamarca*';
  } else if (campo === 'tipo_via') {
    valorGuardado = parseTipoVia(mensajeTexto);
    if (valorGuardado === null) error = 'Elige una opción: *Pavimentada*, *Destapada*, o *Solo camioneta* 🙏';
  } else if (campo === 'fecha_requerida') {
    const d = parseFecha(mensajeTexto, hoyISO);
    if (!d) error = 'No entendí la fecha 🤔 Escribe *hoy*, *mañana*, o una fecha como *25/08*';
    else valorGuardado = toISODate(d);
  } else {
    const v = normalizar(mensajeTexto);
    if (!v) error = 'No me llegó nada de texto — ¿me lo puedes volver a escribir? 🙏';
    else valorGuardado = v;
  }

  if (error) {
    return {
      accion: 'reintentar',
      estado_actual: estado.estado_actual,
      contexto,
      siguiente_pregunta: error,
      solicitud_lista: false,
    };
  }

  contexto[campo] = valorGuardado;

  if ((campo === 'cantidad_animales' || campo === 'peso_promedio_animal') &&
      contexto.cantidad_animales != null && contexto.peso_promedio_animal != null) {
    const toneladas = (contexto.cantidad_animales * contexto.peso_promedio_animal) / 1000;
    contexto.peso_toneladas = Math.round(toneladas * 100) / 100;
  }

  // ── Estamos corrigiendo un dato puntual desde el resumen ──
  if (corrigiendo) {
    const pasosCorreccion = campo === 'tipo_carga' ? pasosPara(valorGuardado) : PASOS;
    const idxCorreccion = pasosCorreccion.indexOf(campo);
    const siguienteCampoCorreccion = pasosCorreccion[idxCorreccion + 1];

    if (campo === 'tipo_carga' || (contexto._corrigiendo_peso && siguienteCampoCorreccion !== 'vereda')) {
      // seguimos encadenados dentro del sub-flujo de peso (cambió el tipo de carga
      // y hay que re-preguntar el/los campo(s) de peso correspondientes antes de
      // volver al resumen) -- igual que en el flujo normal, sin perder el modo corrección.
      contexto._corrigiendo_peso = true;
      return {
        accion: 'avanzar',
        estado_actual: 'esperando_' + siguienteCampoCorreccion,
        contexto,
        siguiente_pregunta: PREGUNTAS[siguienteCampoCorreccion],
