// transferencias). NO exige que el monto de una sola imagen coincida con
// el total del fee -- eso se decide después sumando en la base de datos.
//
// v3: el código de referencia solo se exige SI la imagen trae un campo de
// referencia legible. Varios métodos de pago colombianos (ej. QR de Nequi)
// no tienen forma de escribir una nota/referencia -- exigirla ahí bloqueaba
// pagos reales y válidos sin remedio posible. Si la imagen SÍ trae una
// referencia pero no coincide con la esperada, sigue rechazándose (protege
// contra reusar un comprobante de otro pago).

function parsearRespuestaIA(texto) {
  if (!texto) return null;
  let limpio = texto.trim();
  const m = limpio.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]);
  } catch (e) {
    return null;
  }
}

function validarEstructuraComprobante(extraido, codigoEsperado, cuentaUltimos4Esperado) {
  const fallos = [];

  if (!extraido) {
    return { valido: false, fallos: ['no se pudo interpretar la respuesta de la IA'], extraido: null };
  }
  if (extraido.es_comprobante_pago !== true) {
    fallos.push('la imagen no parece un comprobante de pago');
  }
  if (extraido.confianza === 'baja') {
    fallos.push('la imagen no es lo suficientemente clara para confiar en la lectura');
  }
  if (!extraido.monto || Number(extraido.monto) <= 0) {
    fallos.push('no se pudo leer un monto válido en la imagen');
  }
  if (extraido.referencia) {
    const refLeida = String(extraido.referencia).toUpperCase().replace(/\s+/g, '');
    const refEsperada = String(codigoEsperado || '').toUpperCase().replace(/\s+/g, '');
    if (!refEsperada || !refLeida.includes(refEsperada)) {
      fallos.push('el código de referencia no coincide con el esperado');
    }
  }
  if (cuentaUltimos4Esperado && extraido.cuenta_destino_ultimos4 &&
      String(extraido.cuenta_destino_ultimos4) !== String(cuentaUltimos4Esperado)) {
    fallos.push('la cuenta destino no coincide con la cuenta de TARGO');
  }
  if (!extraido.numero_comprobante) {
    fallos.push('no se pudo leer un número de comprobante único en la imagen');
  }

  return { valido: fallos.length === 0, fallos, extraido };
}

