    let candidata = { y: anio, m: mes, d: dia };
    if (!esFechaValida(candidata)) return null;
    if (!m[3] && esAnterior(candidata, base)) candidata = { y: anio + 1, m: mes, d: dia };
    return candidata;
  }
  return null;
}

function toISODate({ y, m, d }) {
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

// ── Máquina de estados del check-in ──────────────────────────────
function procesarCheckin(estadoActual, contextoIn, mensajeTexto, hoyISO) {
  const contexto = contextoIn || {};

  if (estadoActual === 'checkin_disponible') {
    const resp = parseSiNo(mensajeTexto);
    if (resp === null) {
      return { accion: 'reintentar', estado_actual: 'checkin_disponible', contexto, siguiente_pregunta: 'No te entendí 🤔 Responde *Sí* o *No*: ¿sigues disponible para viajes?' };
    }
    if (resp === false) {
      return { accion: 'completado', tipo_completado: 'pausado', estado_actual: null, contexto: {}, siguiente_pregunta: null, conductor_id: contexto.conductor_id || null, nuevas_zonas: null, nueva_fecha_disponible: null };
    }
    const zonasTxt = (contexto.zonas_actuales || []).length ? (contexto.zonas_actuales || []).join(', ') : 'sin zona registrada';
    return { accion: 'avanzar', estado_actual: 'checkin_zona', contexto, siguiente_pregunta: `📍 ¿Sigues operando en las mismas zonas? (*${zonasTxt}*) Responde *Sí* o *No*.` };
  }

  if (estadoActual === 'checkin_zona') {
    const resp = parseSiNo(mensajeTexto);
    if (resp === null) {
      return { accion: 'reintentar', estado_actual: 'checkin_zona', contexto, siguiente_pregunta: 'No te entendí 🤔 Responde *Sí* o *No*.' };
    }
    if (resp === true) {
      return { accion: 'completado', tipo_completado: 'confirmado', estado_actual: null, contexto: {}, siguiente_pregunta: null, conductor_id: contexto.conductor_id || null, nuevas_zonas: null, nueva_fecha_disponible: null };
    }
    return { accion: 'avanzar', estado_actual: 'checkin_nueva_zona', contexto, siguiente_pregunta: '🗺️ ¿En qué zona(s) estás disponible ahora? (ej: Meta, Valle del Cauca)' };
  }

  if (estadoActual === 'checkin_nueva_zona') {
    const resultado = parseZonas(mensajeTexto);
    if (!resultado.ok || resultado.zonas.length === 0) {
      const invalidasTxt = resultado.invalidas.length ? ` No reconocí: *${resultado.invalidas.join(', ')}*.` : '';
      return { accion: 'reintentar', estado_actual: 'checkin_nueva_zona', contexto, siguiente_pregunta: `🤔${invalidasTxt} Escribe departamentos válidos separados por coma, ej: *Meta, Valle del Cauca*.` };
    }
    contexto.nuevas_zonas = resultado.zonas;
    return { accion: 'avanzar', estado_actual: 'checkin_fecha_disponible', contexto, siguiente_pregunta: '📅 ¿Desde qué fecha estás disponible? (ej: *hoy*, *mañana*, o una fecha como *25/08*)' };
  }

  if (estadoActual === 'checkin_fecha_disponible') {
    const d = parseFecha(mensajeTexto, hoyISO);
    if (!d) {
      return { accion: 'reintentar', estado_actual: 'checkin_fecha_disponible', contexto, siguiente_pregunta: 'No entendí la fecha 🤔 Escribe *hoy*, *mañana*, o una fecha como *25/08*' };
    }
    const fechaISO = toISODate(d);
    return {
      accion: 'completado',
      tipo_completado: 'zona_y_fecha',
      estado_actual: null,
      contexto: {},
      siguiente_pregunta: null,
      conductor_id: contexto.conductor_id || null,
      nuevas_zonas: contexto.nuevas_zonas || null,
      nueva_fecha_disponible: fechaISO,
    };
  }

  return { accion: 'reiniciar', estado_actual: null, contexto: {}, siguiente_pregunta: null, conductor_id: null, nuevas_zonas: null, nueva_fecha_disponible: null };
}

// ── Entrada real del nodo n8n ──────────────────────────────────
const estado = $json || {};
