// en revisión, liberar un conductor atascado, o listar pendientes. Solo
// responde si el mensaje viene del número admin configurado.

const ADMIN_TELEFONO = '573126967940';

function normalizar(s) { return (s || '').trim(); }

const telefonoCrudo = ($('Webhook').item.json.body.sender.phone_number || '').replace('+', '');
const mensajeTexto = $('Webhook').item.json.body.content || '';

if (telefonoCrudo !== ADMIN_TELEFONO) {
  return { es_admin_comando: false, comando: null };
}

const t = normalizar(mensajeTexto);

let m = t.match(/^aprobar\s+#?(\d+)$/i);
if (m) {
  return { es_admin_comando: true, comando: 'aprobar', pago_id: parseInt(m[1], 10) };
}

m = t.match(/^rechazar\s+#?(\d+)$/i);
if (m) {
  return { es_admin_comando: true, comando: 'rechazar', pago_id: parseInt(m[1], 10) };
}

m = t.match(/^liberar\s+(\+?\d{7,15})$/i);
if (m) {
  return { es_admin_comando: true, comando: 'liberar', telefono_objetivo: m[1].replace('+', '') };
}

  m = t.match(/^bloquear\s+(\+?\d{7,15})(?:\s+(.+))?$/i);
  if (m) {
    return { es_admin_comando: true, comando: 'bloquear', telefono_objetivo: m[1].replace('+', ''), motivo: m[2] || 'Bloqueado manualmente por admin' };
  }

  m = t.match(/^desbloquear\s+(\+?\d{7,15})$/i);
  if (m) {
    return { es_admin_comando: true, comando: 'desbloquear', telefono_objetivo: m[1].replace('+', '') };
  }

if (/^pendientes$/i.test(t)) {
  return { es_admin_comando: true, comando: 'pendientes' };
}

return { es_admin_comando: false, comando: null };

